  for(var i=0;i<n;i++){
    var hi=s.charCodeAt(i*2), lo=s.charCodeAt(i*2+1);
    var vh=(hi>=48&&hi<=57)?(hi-48):((hi>=97&&hi<=102)?(hi-87):((hi>=65&&hi<=70)?(hi-55):0));
    var vl=(lo>=48&&lo<=57)?(lo-48):((lo>=97&&lo<=102)?(lo-87):((lo>=65&&lo<=70)?(lo-55):0));
    out[i]=((vh<<4)|vl)&255;
  }
  return out;
}
