function RG_b64d(s){
  var str=String(s||'').replace(/-/g,'+').replace(/_/g,'/');
  // ① android.util.Base64（LT版）
  try{
    var B=Packages.android.util.Base64;
    if(B && typeof B.decode==='function'){
      var r=B.decode(str,0);
      if(r && r.length>0) return r;
    }
  }catch(e){}
  // ② java.util.Base64（E版）
  try{
    var D=Packages.java.util.Base64.getDecoder();
    var r2=D.decode(str);
    if(r2 && r2.length>0) return r2;
  }catch(e2){}
