  for (var i2=0;i2<v8;i2++){
    var old=work[i2], prev=(i2&1)?a:b;
    if (i2&1) a=old; else b=old;
    var pop=0,x=i2; while(x){pop+=x&1;x>>=1;}
    work[i2]=(-21-pop+(prev^old))&255;
