    if(sz===1){ sz=RG_U32(b,p+8)*4294967296+RG_U32(b,p+12); hdr=16; }
    if(sz<hdr) break;
    o.push({t:t,p:p,s:sz,hdr:hdr}); p+=sz;
  }
  return o;
}
