// ---------- 分块处理（大文件用，避免 hex 通道 OOM）----------
// 从头部（含 moov）提取样本索引为简单数组：[offset, size, iv8hex]
function RG_buildIndex(headB){
  var BL = headB.length;
  var moovEnd = BL;
  var top = RG_boxes(headB, 0, Math.min(BL, 2000000));
  for (var i=0;i<top.length;i++){ if(top[i].t==='moov'){ moovEnd=top[i].p+top[i].s; break; } }
  // 总大小：★遍历找 mdat（moov 之后可能有 free/skip 等 box）
  var total = moovEnd;
  var mdatAt = -1;
  var lim = Math.min(BL - 8, moovEnd + 200000);
  for (var q = moovEnd; q < lim; q++) {
    if (RG_STR(headB, q+4, 4) === 'mdat') {
      mdatAt = q;
      total = q + RG_U32(headB, q);
      break;
    }
  }
  // 兜底：用样本最大偏移 + size
  if (mdatAt < 0) {
    var maxEnd = moovEnd;
    // samples 在后面构建，此处先用 stco 粗估
    var stbls0 = RG_find(headB, 28, Math.min(moovEnd, BL), 'stbl');
    for (var z0=0; z0<stbls0.length; z0++){
      var kids0 = RG_boxes(headB, stbls0[z0].p+8, Math.min(stbls0[z0].p+stbls0[z0].s, BL));
      for (var z1=0; z1<kids0.length; z1++){
        if (kids0[z1].t === 'stco') {
          var nch0 = RG_U32(headB, kids0[z1].p+12);
          var lastOff = RG_U32(headB, kids0[z1].p+16+(nch0-1)*4);
          if (lastOff > maxEnd) maxEnd = lastOff;
        }
      }
    }
    if (maxEnd > total) total = maxEnd + 1000000;   // 粗估最后一个 chunk 大小
  }
  // fourcc 修复位置（encv/enca → hev1/mp4a，sinf → free）
  var fixes = [];
  var stsdL = RG_find(headB, 28, Math.min(moovEnd, BL), 'stsd');
  for (var si=0; si<stsdL.length; si++){
    var kk = RG_boxes(headB, stsdL[si].p+16, stsdL[si].p+stsdL[si].s);
    for (var k=0;k<kk.length;k++){
      var e = kk[k];
      if (e.t==='encv'||e.t==='enca'){
        fixes.push({pos: e.p+4, to: (e.t==='encv') ? 'hev1' : 'mp4a'});
        // 找内部 sinf
        var eEnd = Math.min(e.p+e.s, BL);
        for (var p3=e.p+8; p3+8<=eEnd; p3++){
          if ((headB[p3]&255)===0x73&&(headB[p3+1]&255)===0x69&&(headB[p3+2]&255)===0x6e&&(headB[p3+3]&255)===0x66){
            var sz4 = RG_U32(headB, p3-4);
            if (sz4>=8 && p3-4+sz4<=BL){
              fixes.push({pos: p3, to: 'free', zeroFrom: p3+4, zeroTo: p3-4+sz4});
              p3 = p3-4+sz4-1;
            }
          }
        }
      }
    }
  }
  // 样本索引
  var samples = [];
  var stbls = RG_find(headB, 28, Math.min(moovEnd, BL), 'stbl');
  for (var si2=0; si2<stbls.length; si2++){
    var sp = stbls[si2].p, ss = stbls[si2].s;
    var kids = RG_boxes(headB, sp+8, Math.min(sp+ss, BL));
    var senc=null, stsz=null, stco=null, stsc=null;
    for (var i2=0;i2<kids.length;i2++){
      if(kids[i2].t==='senc') senc=kids[i2];
      if(kids[i2].t==='stsz') stsz=kids[i2];
      if(kids[i2].t==='stco') stco=kids[i2];
      if(kids[i2].t==='stsc') stsc=kids[i2];
    }
    if(!senc||!stsz||!stco||!stsc) continue;
    var dflt = RG_U32(headB, stsz.p+12), cnt = RG_U32(headB, stsz.p+16);
    var nch = RG_U32(headB, stco.p+12), nent = RG_U32(headB, stsc.p+12);
    var ef=[], es=[];
    for (var j=0;j<nent;j++){ ef.push(RG_U32(headB, stsc.p+16+j*12)); es.push(RG_U32(headB, stsc.p+16+j*12+4)); }
    var sidx=0, eidx=0;
    for (var c=0; c<nch && sidx<cnt; c++){
      while(eidx+1<nent && ef[eidx+1] <= c+1) eidx++;
      var spc = es[eidx];
      var off = RG_U32(headB, stco.p+16+c*4);
      for (var k2=0; k2<spc && sidx<cnt; k2++){
        var size = dflt ? dflt : RG_U32(headB, stsz.p+20+sidx*4);
        var ivOff = senc.p+16+sidx*8;
        samples.push({off: off, size: size, iv: [
          headB[ivOff]&255, headB[ivOff+1]&255, headB[ivOff+2]&255, headB[ivOff+3]&255,
          headB[ivOff+4]&255, headB[ivOff+5]&255, headB[ivOff+6]&255, headB[ivOff+7]&255
        ]});
        off += size; sidx++;
      }
    }
  }
  return {total: total, moovEnd: moovEnd, fixes: fixes, samples: samples};
}

// 对单个块做解密（blockStart = 块在文件中的起始偏移）
function RG_decryptBlock(block, blockStart, keyHex, samples){
  var BL = block.length;
  var sk = new RG_SK(RG_H2B(keyHex), 'AES');
  var cnt = 0;
  // 二分找到第一个可能重叠的样本
  var lo = 0, hi = samples.length - 1, start = samples.length;
  while (lo <= hi) {
    var mid = (lo + hi) >> 1;
    if (samples[mid].off + samples[mid].size > blockStart) { start = mid; hi = mid - 1; }
    else lo = mid + 1;
  }
  for (var i = start; i < samples.length; i++){
    var s = samples[i];
    if (s.off >= blockStart + BL) break;
    var gEnd = s.off + s.size;
    if (gEnd <= blockStart) continue;
    var os = Math.max(s.off, blockStart) - blockStart;
    var oe = Math.min(gEnd, blockStart + BL) - blockStart;
    if (oe <= os) continue;
    var iv16 = RG_S2B(String.fromCharCode(s.iv[0], s.iv[1], s.iv[2], s.iv[3], s.iv[4], s.iv[5], s.iv[6], s.iv[7], 0,0,0,0,0,0,0,0));
    var cph = RG_CIPHER.getInstance('AES/CTR/NoPadding');
    cph.init(RG_CIPHER.DECRYPT_MODE, sk, new RG_IVP(iv16));
    var dec = cph.doFinal(RG_ARR.copyOfRange(block, os, oe));
    RG_SYS.arraycopy(dec, 0, block, os, oe - os);
    cnt++;
  }
  return cnt;
}

// 应用 fourcc 修复到块（如果块包含修复位置）
function RG_applyFixes(block, blockStart, fixes){
  for (var i=0; i<fixes.length; i++){
    var f = fixes[i];
    if (f.pos >= blockStart && f.pos + 4 <= blockStart + block.length) {
      var p = f.pos - blockStart;
      block[p] = f.to.charCodeAt(0); block[p+1] = f.to.charCodeAt(1);
      block[p+2] = f.to.charCodeAt(2); block[p+3] = f.to.charCodeAt(3);
      if (f.zeroFrom !== undefined) {
        var zs = Math.max(f.zeroFrom, blockStart) - blockStart;
        var ze = Math.min(f.zeroTo, blockStart + block.length) - blockStart;
        for (var z = zs; z < ze; z++) block[z] = 0;
      }
    }
  }
}

// 播放数据（preload + fallback）
// ★ 关键：video_model.video_list[].main_url 是明文 URL；
//   fallback_api 响应里的 video_list.video_N.main_url 才是 spade 密文（需解密）
function HG_playData(JV, vid, sid){
  var BP = {detail_page_version:0,device_level:3,disable_digg_stat:false,need_all_video_definition:true,
  need_mp4_align:false,use_os_player:false,use_server_dns:false,video_platform:1024};
  var raw = String(HG_API(JV,'/novel/player/multi_video_model/preload/v1',{biz_param:BP,dr_scene:'preload',mixed_video_id_map:{'1004':[vid]}}));
  var j = null; try { j = JSON.parse(raw); } catch(e) {}
  if (!j || j.code !== 0 || !j.data) return null;
  var entry = j.data[vid] || j.data[Object.keys(j.data)[0]];
  if (!entry || !entry.video_model) return null;
  var vm = typeof entry.video_model === 'string' ? JSON.parse(entry.video_model) : entry.video_model;
  // 画质偏好：默认 720p，可用书源变量 hgq 覆盖（360/480/540/720/1080）
  var prefQ = '';
  try { prefQ = String(JV.get ? (JV.get('hgq') || '') : ''); } catch(e0) {}
  if (!prefQ) { try { prefQ = String(source.get('hgq') || ''); } catch(e1) {} }
  if (!prefQ) prefQ = '480';   // 默认 480p：平衡内存与清晰度（720p+ 在校验器连续执行时可能 OOM）
  var wantDef = prefQ + 'p';
  // ★只选 bytevc1（标准 H.265 / hvcC）：bytevc2 是 ByteDance 私有 bv2C 编码，Android 解码器不支持
  function isStdCodec(v){ return String((v.video_meta||{}).codec_type||'') === 'bytevc1'; }
  // 第一优先：目标清晰度 + bytevc1
  var pick = null, pickSpadeA = '', pickDef = '';
  for (var i = 0; i < vm.video_list.length; i++) {
    var v = vm.video_list[i];
    var ei = v.encrypt_info || {};
    if (!ei.spade_a) continue;
    var def = String((v.video_meta||{}).definition||'');
    if (def === wantDef && isStdCodec(v)) { pick = v; pickSpadeA = String(ei.spade_a); pickDef = def; break; }
  }
  // 第二优先：任意 bytevc1（选 size 最大）
  if (!pick) {
    var bestSize = -1;
    for (var i2 = 0; i2 < vm.video_list.length; i2++) {
      var v2 = vm.video_list[i2];
      var ei2 = v2.encrypt_info || {};
      if (!ei2.spade_a || !isStdCodec(v2)) continue;
      var sz = parseInt((v2.video_meta||{}).size || '0', 10) || 0;
      if (sz > bestSize) { bestSize = sz; pick = v2; pickSpadeA = String(ei2.spade_a); pickDef = String((v2.video_meta||{}).definition||''); }
    }
  }
  // 第三优先（兜底）：目标清晰度，任意 codec（可能会遇到 bv2C）
  if (!pick) {
    for (var i3 = 0; i3 < vm.video_list.length; i3++) {
      var v3 = vm.video_list[i3];
      var ei3 = v3.encrypt_info || {};
      if (!ei3.spade_a) continue;
      var def3 = String((v3.video_meta||{}).definition||'');
      if (def3 === wantDef) { pick = v3; pickSpadeA = String(ei3.spade_a); pickDef = def3; break; }
    }
  }
  if (!pick) return null;
  // ★体积上限：hex 通道内存峰值约为文件的 2 倍，超过 24MB 会 OOM
  // 优先在选中档位中找 ≤ 上限的；找不到则用最小的（并标记）
  var maxMB = 20;
  try { var mv = String(source.get('hgmax') || ''); if (mv) maxMB = parseInt(mv, 10) || 24; } catch(e5) {}
  var maxBytes = maxMB * 1048576;
  var pickSize = parseInt((pick.video_meta||{}).size || '0', 10) || 0;
  // ★体积上限：写文件需 hex 字符串（约 4×文件字节），20MB 文件约需 80MB 峰值；再大必然 OOM
  if (pickSize > maxBytes) {
    var wantStd = isStdCodec(pick);
    var alt = null, altSize = -1, altSpadeA = '', altDef = '';
    for (var i4 = 0; i4 < vm.video_list.length; i4++) {
      var v4 = vm.video_list[i4];
      var ei4 = v4.encrypt_info || {};
      if (!ei4.spade_a) continue;
      if (isStdCodec(v4) !== wantStd) continue;
      var sz4 = parseInt((v4.video_meta||{}).size || '0', 10) || 0;
      if (sz4 <= maxBytes && sz4 > altSize) { altSize = sz4; alt = v4; altSpadeA = String(ei4.spade_a); altDef = String((v4.video_meta||{}).definition||''); }
    }
    if (alt) { pick = alt; pickSpadeA = altSpadeA; pickDef = altDef; pickSize = altSize; }
    else { return { spade: null, spadeA: null, seed: null, def: pickDef, tooBig: true, sizeMB: (pickSize/1048576).toFixed(0) }; }
  }
  var bestSpadeA = pickSpadeA, bestDef = pickDef;
  // fallback 响应里才有 spade 密文 URL + key_seed
  var fb = vm.fallback_api && vm.fallback_api.fallback_api;
  if (!fb) return null;
  var fbr = String(JV.ajax(fb + ','+String.fromCharCode(123,34,104,101,97,100,101,114,115,34,58,123,34,85,115,101,114,45,65,103,101,110,116,34,58,34,99,111,109,46,112,104,111,101,110,105,120,46,114,101,97,100,47,55,50,57,51,50,34,125,125)));
  var fj = null; try { fj = JSON.parse(fbr); } catch(e) {}
  if (!fj || !fj.video_info || !fj.video_info.data) return null;
  var fd = fj.video_info.data;
  var seed = String(fd.key_seed || '');
  if (!seed) return null;
  var fvl = fd.video_list || {};
  // 优先按 definition 匹配；否则取 size 最大的
  var bestUrl = '', bestFs = -1, exactUrl = '';
  for (var k in fvl) {
    var fv = fvl[k] || {};
    var mu = String(fv.main_url || '');
    if (!mu || mu.indexOf('http') === 0) continue;   // 只要 spade 密文
    var fdef = String(fv.definition || '');
    if (fdef === bestDef) exactUrl = mu;
    var fsz = parseInt(fv.size || '0', 10) || 0;
    if (fsz > bestFs) { bestFs = fsz; bestUrl = mu; }
  }
  if (exactUrl) bestUrl = exactUrl;
  if (!bestUrl) return null;
  return { spade: bestUrl, spadeA: bestSpadeA, seed: seed, def: bestDef, sizeMB: ((parseInt((pick.video_meta||{}).size||'0',10)||0)/1048576).toFixed(1) };
}

