  if(v.score) k.push(String(v.score)+'分');
  if(v.play_cnt) k.push(String(Math.round(Number(v.play_cnt)/10000))+'万播放');
  return JSON.stringify({name:t,author:'番茄短剧',kind:k.join(' · '),
    intro:String(v.video_desc||v.series_intro||''),
