// —— 播放：shortplay 通道（aid=1967，各档位 bytevc1 可播，URL 为 base64 明文）——
function FV_playData(JV, vid){
  var u='https://api3-normal-sinfonlinea.fqnovel.com/novel/player/video_model/v1/'
    +'?iid=4439167111854618&device_id=4439167111850522&aid=1967&app_name=novelapp'
    +'&version_code=72132&version_name=7.2.1.32&device_platform=android&device_brand=Xiaomi'
    +'&os_version=13&cdid=6100e9f9-a1a0-4f65-ab47-94f5b41b8efb';
  var BP={detail_page_version:0,device_level:3,disable_digg_stat:false,disable_video_relate_book:false,
    from_video_id:'',need_all_video_definition:true,need_mp4_align:false,source:4,
    use_os_player:false,use_server_dns:false,video_platform:3};
  var body={video_id:String(vid),content_type:1004,biz_param:BP};
  var bs=JSON.stringify(body);
  var h={'user-agent':'com.dragon.read','Content-Type':'application/json'};
  h['x-ss-stub']=HG_hx(HG_md5(HG_u8(bs))).toUpperCase();
  var sg=HG_sign(u,{headers:h,body:bs});
  for(var k in sg) h[k]=sg[k];
  var r=String(JV.ajax(u+','+JSON.stringify({method:'POST',headers:h,body:bs})));
  var j=null; try{ j=JSON.parse(r); }catch(e){ return null; }
  if(j.code!==0||!j.data||!j.data.video_model) return null;
  var vm=null;
  try{ vm=(typeof j.data.video_model==='string')?JSON.parse(j.data.video_model):j.data.video_model; }catch(e2){ return null; }
  var vl=vm.video_list;
  if(!vl) return null;
  // 画质偏好：source.get('hgq') 覆盖（360/480/540/720），默认 360（体积小、解密快）
  var prefQ='';
  try{ prefQ=String(JV.get?JV.get('hgq'):''); }catch(e3){}
  if(!prefQ){ try{ prefQ=String(source.get('hgq')||''); }catch(e4){} }
  if(!prefQ) prefQ='360';
  var want=prefQ+'p';
  var pick=null;
  for(var kk in vl){
    var v=vl[kk];
    if(String(v.definition||'')===want && String(v.codec_type||'')==='bytevc1'){ pick=v; break; }
  }
  if(!pick){
    var best=-1;
    for(var k2 in vl){
      var v2=vl[k2];
      if(String(v2.codec_type||'')!=='bytevc1') continue;
      var sz=parseInt(v2.size||'0',10)||0;
      if(sz>best){ best=sz; pick=v2; }
    }
  }
  if(!pick){
    for(var k3 in vl){ var v3=vl[k3]; if(String(v3.definition||'')===want){ pick=v3; break; } }
  }
  if(!pick) return null;
  var url64=String(pick.main_url||'');
  if(!url64) return null;
  var realUrl='';
  try{ realUrl=String(new Packages.java.lang.String(RG_b64d(url64),'UTF-8')); }catch(e5){
    try{ realUrl=String(new Packages.java.lang.String(Packages.java.util.Base64.getDecoder().decode(url64),'UTF-8')); }catch(e6){ return null; }
  }
  if(realUrl.indexOf('http')!==0) return null;
  var size=parseInt(pick.size||'0',10)||0;
  return {url:realUrl,def:String(pick.definition||''),size:size,
    sizeMB:Math.round(size/1048576),spadeA:String(pick.spade_a||''),
    bv2c:(String(pick.codec_type||'').indexOf('bytevc2')>=0)};
}

