function FV_trimCache(JV,SV){
  try{
    var keys=String(SV.get('fv_keys')||'');
    var arr=keys?keys.split(','):[];
    var MAXK=6;
    while(arr.length>MAXK){
      var oldKey=arr.shift();
      try{
        var p=String(SV.get(oldKey)||'');
        if(p){ try{ JV.deleteFile(p); }catch(e1){} }
        SV.put(oldKey,'');
      }catch(e2){}
    }
    SV.put('fv_keys',arr.join(','));
  }catch(e3){}
}

// ★动态探测缓存目录（跨版本兼容：不同 App 包名不同）
function FV_cacheDir(JV){
  var jv = JV || java;   // 优先用传入的 JV（规则上下文），回退全局 java（eval_js 上下文）
  try{ jv.readFile('/'); }catch(e){
    var m=String(e).match(/([/]storage[/]emulated[/]0[/]Android[/]data[/][^/]+[/]cache)/);
    if(m) return m[1];
    var m2=String(e).match(/([/]data[/]data[/][^/]+[/]cache)/);
    if(m2) return m2[1];
  }
  return '';
}

